BEGIN;

CREATE OR REPLACE FUNCTION public.office_hospitality_command(p_workspace_id uuid,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE rn text;ik uuid;h text;result jsonb;res text;d jsonb;id uuid;v bigint;st text;prop uuid;room uuid;target uuid;old jsonb; q numeric; net numeric;tax numeric;levy numeric;total numeric;method text; allowed text[]; key text; BEGIN
 rn:=office_private.hospitality_context(p_workspace_id);
 IF jsonb_typeof(p_payload)<>'object' OR NOT(p_payload ? 'idempotency_key') THEN RAISE EXCEPTION 'Every mutation requires idempotency_key' USING ERRCODE='22023'; END IF;
 ik:=office_private.hospitality_uuid(p_payload->>'idempotency_key','idempotency_key');
 IF to_regprocedure('public.digest(bytea,text)') IS NOT NULL THEN h:=encode(public.digest(convert_to(p_action||':'||(p_payload-'idempotency_key')::text,'UTF8'),'sha256'),'hex'); ELSE h:=md5(p_action||':'||(p_payload-'idempotency_key')::text); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||auth.uid()::text||':'||ik::text,0));
 SELECT response INTO result FROM public.office_hospitality_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=ik FOR UPDATE;
 IF result IS NOT NULL THEN IF (SELECT request_hash FROM public.office_hospitality_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=ik)<>h OR (SELECT action FROM public.office_hospitality_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=ik)<>p_action THEN RAISE EXCEPTION 'Idempotency key reused with different body' USING ERRCODE='23505'; END IF; RETURN result; END IF;
 p_payload := p_payload-'idempotency_key';
 allowed:=CASE
 WHEN p_action='initialize' THEN ARRAY[]::text[]
 WHEN p_action='configure_settings' THEN ARRAY['base_currency','jurisdiction','expected_version']
 WHEN p_action='configure_private_key' THEN ARRAY['kind','salt','nonce','ciphertext']
 WHEN p_action='set_private_gate' THEN ARRAY['enabled','storage_review_state','storage_review_reference','expected_version']
 WHEN p_action IN ('save_record','save_guest') THEN ARRAY['resource','id','expected_version','data']
 WHEN p_action='transition_record' THEN ARRAY['resource','id','expected_version','to_state','data']
 WHEN p_action IN ('check_in','check_out') THEN ARRAY['id','expected_version']
 WHEN p_action='move_room' THEN ARRAY['id','expected_version','room_id','reference']
 WHEN p_action='assign_role' THEN ARRAY['user_id','role','active','expected_version']
 WHEN p_action='post_charge' THEN ARRAY['reservation_id','expected_version','description_public','net_amount','tax_amount','levy_amount','reference']
 WHEN p_action='void_charge' THEN ARRAY['reservation_id','expected_version','line_id','reference']
 WHEN p_action IN ('record_payment','refund_payment') THEN ARRAY['reservation_id','expected_version','amount','method','reference','payment_id']
 WHEN p_action='close_day' THEN ARRAY['property_id','close_on','cash_actual','bank_actual','mobile_actual','card_actual','reference']
 WHEN p_action='create_report' THEN ARRAY['property_id','period_start','period_end','title','report_type']
 WHEN p_action='export_report' THEN ARRAY['id','expected_version','purpose']
 WHEN p_action='receive_stock' THEN ARRAY['property_id','item_id','lot_code','expires_on','quantity','unit_cost','reference']
 WHEN p_action='issue_stock' THEN ARRAY['id','expected_version','quantity','reference']
 WHEN p_action='add_order_line' THEN ARRAY['id','expected_version','item_id','quantity']
 WHEN p_action='settle_order' THEN ARRAY['id','expected_version','method','reference','reservation_id']
 ELSE NULL END;
 IF allowed IS NULL THEN RAISE EXCEPTION 'Unsupported hospitality action' USING ERRCODE='0A000'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE NOT (k=ANY(allowed))) THEN RAISE EXCEPTION 'Unknown top-level payload field' USING ERRCODE='22023'; END IF;
 IF p_action='assign_role' THEN
   IF rn<>'hotel_admin' THEN RAISE EXCEPTION 'Role management requires hotel admin' USING ERRCODE='42501'; END IF;
   IF p_payload->>'role' NOT IN ('hotel_admin','front_desk','cashier','housekeeper','maintenance_engineer','fnb_manager','hr_officer','compliance_officer','hotel_viewer') OR p_payload->>'active' NOT IN ('true','false') THEN RAISE EXCEPTION 'Invalid role assignment' USING ERRCODE='22023'; END IF;
   id:=office_private.hospitality_uuid(p_payload->>'user_id','user_id');
   IF NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=id AND m.status='active') THEN RAISE EXCEPTION 'Assigned user must be an active workspace member' USING ERRCODE='42501'; END IF;
   IF p_payload ? 'expected_version' THEN IF p_payload->>'expected_version' !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'Positive expected_version required'; END IF; UPDATE public.office_hospitality_roles SET role=p_payload->>'role',active=(p_payload->>'active')::boolean,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND user_id=id AND version=(p_payload->>'expected_version')::bigint RETURNING version INTO v; IF v IS NULL THEN RAISE EXCEPTION 'Stale or missing role' USING ERRCODE='40001'; END IF; ELSE INSERT INTO public.office_hospitality_roles(workspace_id,user_id,role,active) VALUES(p_workspace_id,id,p_payload->>'role',(p_payload->>'active')::boolean) ON CONFLICT(workspace_id,user_id) DO NOTHING; SELECT version INTO v FROM public.office_hospitality_roles WHERE workspace_id=p_workspace_id AND user_id=id; IF v<>1 THEN RAISE EXCEPTION 'Existing role requires expected_version' USING ERRCODE='40001'; END IF; END IF; result:=jsonb_build_object('id',p_workspace_id,'version',v,'status','role_assigned');
 ELSIF p_action IN ('post_charge','void_charge','record_payment','refund_payment','close_day','create_report','export_report') THEN
   result:=office_private.hospitality_finance_action(p_workspace_id,rn,p_action,p_payload);
 ELSIF p_action IN ('receive_stock','issue_stock','add_order_line','settle_order') THEN
   result:=office_private.hospitality_food_stock_action(p_workspace_id,rn,p_action,p_payload);
 ELSIF p_action IN ('save_record','transition_record') AND p_payload->>'resource' IN ('events','shifts','evidence','housekeeping','maintenance','licences') THEN
   result:=office_private.hospitality_operations_action(p_workspace_id,rn,p_action,p_payload->>'resource',p_payload);
 END IF;
 IF result IS NOT NULL THEN
   INSERT INTO public.office_hospitality_idempotency(workspace_id,actor_id,idempotency_key,action,request_hash,response) VALUES(p_workspace_id,auth.uid(),ik,p_action,h,result);
   IF p_action NOT IN ('receive_stock','issue_stock','add_order_line','settle_order','export_report') THEN PERFORM office_private.hospitality_audit(p_workspace_id,coalesce(p_payload->>'resource',p_action),p_action,(result->>'id')::uuid,NULL,jsonb_build_object('status',result->>'status')); END IF;
   RETURN result;
 END IF;
 IF p_action='initialize' THEN PERFORM office_private.hospitality_require_cap(rn,'properties','initialize');INSERT INTO public.office_hospitality_settings(workspace_id,initialized) VALUES(p_workspace_id,true) ON CONFLICT(workspace_id) DO UPDATE SET initialized=true,updated_at=now();result:=jsonb_build_object('id',p_workspace_id,'version',1,'status','initialized');
 ELSIF p_action='configure_settings' THEN PERFORM office_private.hospitality_require_cap(rn,'properties','configure');IF NOT(p_payload ? 'expected_version') OR (p_payload->>'expected_version')::bigint<1 OR p_payload->>'base_currency' !~ '^[A-Z]{3}$' OR p_payload->>'jurisdiction' NOT IN('mainland','zanzibar') THEN RAISE EXCEPTION 'Invalid settings';END IF;UPDATE public.office_hospitality_settings SET base_currency=p_payload->>'base_currency',jurisdiction=p_payload->>'jurisdiction',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND version=(p_payload->>'expected_version')::bigint;IF NOT FOUND THEN RAISE EXCEPTION 'Stale settings version' USING ERRCODE='40001';END IF;SELECT version INTO v FROM public.office_hospitality_settings WHERE workspace_id=p_workspace_id;result:=jsonb_build_object('id',p_workspace_id,'version',v,'status','configured');
 ELSIF p_action='configure_private_key' THEN IF rn NOT IN('hotel_admin','compliance_officer') OR p_payload->>'kind' NOT IN('guest','incident') THEN RAISE EXCEPTION 'Private key capability required' USING ERRCODE='42501';END IF;INSERT INTO public.office_hospitality_private_keys(workspace_id,kind,configured,key_version,derivation,iterations,salt,nonce,ciphertext) VALUES(p_workspace_id,p_payload->>'kind',true,1,'PBKDF2-HMAC-SHA-256/AES-256-GCM',600000,decode(p_payload->>'salt','base64'),decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64')) ON CONFLICT(workspace_id,kind) DO NOTHING; IF NOT FOUND THEN RAISE EXCEPTION 'Private key already configured' USING ERRCODE='23505'; END IF; result:=jsonb_build_object('id',p_workspace_id,'version',1,'status','configured');
 ELSIF p_action='set_private_gate' THEN IF rn<>'hotel_admin' OR NOT(p_payload ? 'expected_version') THEN RAISE EXCEPTION 'Admin gate and expected version required';END IF;IF coalesce((p_payload->>'enabled')::boolean,false) AND (p_payload->>'storage_review_state'<>'approved' OR btrim(coalesce(p_payload->>'storage_review_reference',''))='' OR NOT EXISTS(SELECT 1 FROM public.office_hospitality_private_keys WHERE workspace_id=p_workspace_id AND kind='guest' AND configured)) THEN RAISE EXCEPTION 'Approved review and guest key required' USING ERRCODE='55000';END IF;IF p_payload->>'enabled' NOT IN ('true','false') THEN RAISE EXCEPTION 'enabled must be boolean'; END IF; UPDATE public.office_hospitality_settings SET private_data_enabled=(p_payload->>'enabled')::boolean,storage_review_state=coalesce(p_payload->>'storage_review_state',storage_review_state),storage_review_reference=CASE WHEN p_payload ? 'storage_review_reference' THEN NULLIF(btrim(p_payload->>'storage_review_reference'),'') ELSE storage_review_reference END,version=version+1 WHERE workspace_id=p_workspace_id AND version=(p_payload->>'expected_version')::bigint;IF NOT FOUND THEN RAISE EXCEPTION 'Stale settings version' USING ERRCODE='40001';END IF;SELECT version INTO v FROM public.office_hospitality_settings WHERE workspace_id=p_workspace_id;result:=jsonb_build_object('id',p_workspace_id,'version',v,'status','gate_changed');
 ELSIF p_action='save_record' OR p_action='save_guest' THEN res:=CASE WHEN p_action='save_guest' THEN 'guests' ELSE p_payload->>'resource' END;d:=p_payload->'data';PERFORM office_private.hospitality_require_cap(rn,res,'save');PERFORM office_private.hospitality_validate(res,d);IF res<>'properties' AND NOT EXISTS(SELECT 1 FROM public.office_hospitality_properties pr WHERE pr.id=(d->>'property_id')::uuid AND pr.workspace_id=p_workspace_id AND pr.status='active') THEN RAISE EXCEPTION 'Active same-workspace property required';END IF;IF res IN('guests','incidents') AND (NOT EXISTS(SELECT 1 FROM public.office_hospitality_settings s WHERE s.workspace_id=p_workspace_id AND s.private_data_enabled AND s.storage_review_state='approved') OR NOT EXISTS(SELECT 1 FROM public.office_hospitality_private_keys WHERE workspace_id=p_workspace_id AND kind=CASE WHEN res='guests' THEN 'guest' ELSE 'incident' END AND configured)) THEN RAISE EXCEPTION 'Private key required' USING ERRCODE='55000';END IF;IF res='reservations' AND EXISTS(SELECT 1 FROM public.office_hospitality_reservations x WHERE x.workspace_id=p_workspace_id AND x.property_id=(d->>'property_id')::uuid AND x.data->>'room_id'=d->>'room_id' AND x.status IN('provisional','confirmed','checked_in') AND office_private.hospitality_date(x.data->>'check_in_on')<office_private.hospitality_date(d->>'check_out_on') AND office_private.hospitality_date(x.data->>'check_out_on')>office_private.hospitality_date(d->>'check_in_on')) THEN RAISE EXCEPTION 'Room booking overlap' USING ERRCODE='23P01';END IF;id:=coalesce((p_payload->>'id')::uuid,gen_random_uuid());IF p_payload ? 'id' AND NOT(p_payload ? 'expected_version') THEN IF EXISTS(SELECT 1 FROM public.office_hospitality_guests g WHERE g.workspace_id=p_workspace_id AND g.id=(p_payload->>'id')::uuid) THEN RAISE EXCEPTION 'Existing encrypted guest requires expected_version' USING ERRCODE='40001';END IF;END IF;IF p_payload ? 'expected_version' THEN IF (p_payload->>'expected_version')::bigint<1 THEN RAISE EXCEPTION 'Positive expected_version required';END IF;EXECUTE format('UPDATE public.office_hospitality_%I SET data=$1,version=version+1,updated_at=now() WHERE workspace_id=$2 AND id=$3 AND version=$4 RETURNING version,status',res) INTO v,st USING d,p_workspace_id,id,(p_payload->>'expected_version')::bigint;IF v IS NULL THEN RAISE EXCEPTION 'Stale or missing record' USING ERRCODE='40001';END IF;ELSE st:=CASE res WHEN 'rooms' THEN 'dirty' WHEN 'reservations' THEN 'provisional' WHEN 'housekeeping' THEN 'open' WHEN 'maintenance' THEN 'open' WHEN 'restaurant_orders' THEN 'open' WHEN 'events' THEN 'inquiry' WHEN 'licences' THEN 'draft' WHEN 'food_safety' THEN 'recorded' WHEN 'guests' THEN 'active' WHEN 'incidents' THEN 'reported' ELSE 'active' END;EXECUTE format('INSERT INTO public.office_hospitality_%I(id,workspace_id,property_id,status,created_by,data) VALUES($1,$2,($3->>''property_id'')::uuid,$4,auth.uid(),$3)',res) USING id,p_workspace_id,d,st;v:=1;END IF;result:=jsonb_build_object('id',id,'version',v,'status',st);
 ELSIF p_action='transition_record' THEN res:=p_payload->>'resource';PERFORM office_private.hospitality_require_cap(rn,res,'transition');IF NOT(p_payload ? 'expected_version') OR (p_payload->>'expected_version')::bigint<1 THEN RAISE EXCEPTION 'Positive expected_version required';END IF;id:=office_private.hospitality_uuid(p_payload->>'id','id');EXECUTE format('SELECT status,version,property_id,data FROM public.office_hospitality_%I WHERE workspace_id=$1 AND id=$2 FOR UPDATE',res) INTO st,v,prop,d USING p_workspace_id,id;IF v IS NULL OR v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale record' USING ERRCODE='40001';END IF;IF res='rooms' AND NOT((st='dirty' AND p_payload->>'to_state'='clean') OR(st='clean' AND p_payload->>'to_state'='inspected') OR(st='inspected' AND p_payload->>'to_state'='dirty') OR(st IN('dirty','clean','inspected') AND p_payload->>'to_state' IN('out_of_order','out_of_service'))) THEN RAISE EXCEPTION 'Invalid room transition';END IF;IF res='reservations' AND NOT((st='provisional' AND p_payload->>'to_state' IN('confirmed','cancelled')) OR(st='confirmed' AND p_payload->>'to_state' IN('cancelled','no_show'))) THEN RAISE EXCEPTION 'Invalid reservation transition';END IF;IF res='maintenance' AND NOT((st='open' AND p_payload->>'to_state' IN('triaged','cancelled')) OR(st='triaged' AND p_payload->>'to_state'='assigned') OR(st='assigned' AND p_payload->>'to_state'='in_progress') OR(st='in_progress' AND p_payload->>'to_state' IN('awaiting_parts','resolved')) OR(st='awaiting_parts' AND p_payload->>'to_state'='in_progress') OR(st='resolved' AND p_payload->>'to_state'='verified') OR(st='verified' AND p_payload->>'to_state'='closed')) THEN RAISE EXCEPTION 'Invalid maintenance transition';END IF;IF res='maintenance' AND p_payload->>'to_state' IN('verified','closed') AND btrim(coalesce(p_payload->'data'->>'reference',''))='' THEN RAISE EXCEPTION 'Verification reference required';END IF;EXECUTE format('UPDATE public.office_hospitality_%I SET status=$1,version=version+1,updated_at=now() WHERE workspace_id=$2 AND id=$3 AND version=$4 RETURNING version',res) INTO v USING p_payload->>'to_state',p_workspace_id,id,(p_payload->>'expected_version')::bigint;result:=jsonb_build_object('id',id,'version',v,'status',p_payload->>'to_state');
 ELSIF p_action IN('check_in','check_out','move_room') THEN IF p_payload->>'expected_version' !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'Positive expected_version required'; END IF; IF p_action='move_room' AND btrim(coalesce(p_payload->>'reference',''))='' THEN RAISE EXCEPTION 'Move reference required'; END IF; PERFORM office_private.hospitality_require_cap(rn,'reservations',p_action);id:=office_private.hospitality_uuid(p_payload->>'id','id');SELECT data,status,version,property_id INTO d,st,v,prop FROM public.office_hospitality_reservations r WHERE r.workspace_id=p_workspace_id AND r.id=id FOR UPDATE;IF v IS NULL OR v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale reservation';END IF;room:=(d->>'room_id')::uuid;IF p_action='check_in' THEN IF st<>'confirmed' OR NOT EXISTS(SELECT 1 FROM public.office_hospitality_rooms WHERE id=room AND property_id=prop AND status='inspected') THEN RAISE EXCEPTION 'Confirmed reservation and inspected room required';END IF;UPDATE public.office_hospitality_reservations r SET status='checked_in',version=r.version+1 WHERE r.workspace_id=p_workspace_id AND r.id=id;UPDATE public.office_hospitality_rooms SET status='occupied',version=version+1 WHERE workspace_id=p_workspace_id AND id=room;result:=jsonb_build_object('id',id,'version',v+1,'status','checked_in');ELSIF p_action='check_out' THEN IF st<>'checked_in' OR (SELECT coalesce(sum((data->>'total_amount')::numeric) FILTER(WHERE status<>'voided'),0) FROM public.office_hospitality_folio_lines WHERE workspace_id=p_workspace_id AND data->>'reservation_id'=id::text)>(SELECT coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='payment'),0)-coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='refund'),0) FROM public.office_hospitality_payments WHERE workspace_id=p_workspace_id AND data->>'reservation_id'=id::text) THEN RAISE EXCEPTION 'Zero balance required';END IF;UPDATE public.office_hospitality_reservations r SET status='checked_out',version=r.version+1 WHERE r.workspace_id=p_workspace_id AND r.id=id;UPDATE public.office_hospitality_rooms SET status='dirty',version=version+1 WHERE workspace_id=p_workspace_id AND id=room;result:=jsonb_build_object('id',id,'version',v+1,'status','checked_out');ELSE target:=office_private.hospitality_uuid(p_payload->>'room_id','room_id');IF st<>'checked_in' OR NOT EXISTS(SELECT 1 FROM public.office_hospitality_rooms WHERE workspace_id=p_workspace_id AND id=target AND property_id=prop AND status='inspected') THEN RAISE EXCEPTION 'Move requires inspected same-property target';END IF;UPDATE public.office_hospitality_rooms SET status='dirty',version=version+1 WHERE workspace_id=p_workspace_id AND id=room;UPDATE public.office_hospitality_rooms SET status='occupied',version=version+1 WHERE workspace_id=p_workspace_id AND id=target;UPDATE public.office_hospitality_reservations r SET data=jsonb_set(r.data,'{room_id}',to_jsonb(target::text)),version=r.version+1 WHERE r.workspace_id=p_workspace_id AND r.id=id;result:=jsonb_build_object('id',id,'version',v+1,'status','checked_in');END IF;
 ELSE RAISE EXCEPTION 'Unsupported hospitality action' USING ERRCODE='0A000';END IF;
 INSERT INTO public.office_hospitality_idempotency(workspace_id,actor_id,idempotency_key,action,request_hash,response) VALUES(p_workspace_id,auth.uid(),ik,p_action,h,result);PERFORM office_private.hospitality_audit(p_workspace_id,coalesce(res,p_action),p_action,(result->>'id')::uuid,NULL,jsonb_build_object('status',result->>'status'));RETURN result;END$$;


REVOKE ALL ON FUNCTION public.office_hospitality_command(uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.office_hospitality_command(uuid,text,jsonb) TO authenticated;

COMMIT;
